mapper.select:
SELECT ENABLED
  FROM MEMBER_NOTIFICATION_SETTING
 WHERE MEMBER_ID = #{memberId}
   AND NOTI_TYPE = #{notiType}

SELECT s.MEMBER_ID
  FROM MEMBER_NOTIFICATION_SETTING s
  JOIN MEMBER m ON m.ID = s.MEMBER_ID
 WHERE m.CHALLENGE_ID = #{challengeId}
   AND s.NOTI_TYPE = #{notiType}
   AND s.ENABLED = 'N'
